PIPELINE_SOURCES = {'01_setup_and_config': '# Databricks notebook source\n# MAGIC %md\n# MAGIC # 01 - Setup And Configuration\n# MAGIC\n# MAGIC This notebook defines project configuration, database/schema names, table names, processing parameters, and helper functions used by later notebooks.\n\n# COMMAND ----------\n\nfrom datetime import date, datetime, timedelta, timezone\nimport re\nfrom uuid import uuid4\nfrom pyspark.sql import functions as F\nfrom pyspark.sql.types import StructType, StructField, StringType, IntegerType, DoubleType, TimestampType\n\n# COMMAND ----------\n\n# DBTITLE 1,Create Widgets If Needed\nproject_name = "nyc_taxi_lakehouse"\n_active_context = globals().get("_pipeline_context", {})\nif not isinstance(_active_context, dict):\n    raise ValueError("Pipeline context must be a dictionary")\n# Project policy, not a guarantee about TLC publication/event-time semantics.\nboundary_grace_days = _active_context.get("boundary_grace_days", 1)\ndate_policy_version = "quality_v2_pickup_grace_numeric_contract"\n\nif "process_year" in _active_context and "process_month" in _active_context:\n    process_year = str(_active_context["process_year"])\n    process_month = str(_active_context["process_month"]).zfill(2)\nelse:\n    dbutils.widgets.text("process_year", "2024", "Process Year")\n    dbutils.widgets.text("process_month", "01", "Process Month")\n    process_year = str(_active_context.get("process_year", dbutils.widgets.get("process_year")))\n    process_month = str(_active_context.get("process_month", dbutils.widgets.get("process_month"))).zfill(2)\nif not (2009 <= int(process_year) <= datetime.now(timezone.utc).year and 1 <= int(process_month) <= 12):\n    raise ValueError("Invalid processing year/month")\nbatch_id = _active_context.get("batch_id") or f"{project_name}_{process_year}_{process_month}_{uuid4().hex}"\nrun_started_at = _active_context.get("run_started_at") or datetime.now(timezone.utc).isoformat()\n# Stable wall-clock derivation; source timestamps are not claimed to be NYC-to-UTC converted.\nspark.conf.set("spark.sql.session.timeZone", "UTC")\n\nprint(f"project_name={project_name}")\nprint(f"process_year={process_year}")\nprint(f"process_month={process_month}")\nprint(f"batch_id={batch_id}")\nprint(f"date_policy_version={date_policy_version}, boundary_grace_days={boundary_grace_days}")\n\n# COMMAND ----------\n\n# DBTITLE 1,Database And Table Names\ncatalog_name = _active_context.get("catalog_name", "workspace")\nschema_name = _active_context.get("schema_name", project_name)\nfor identifier in [catalog_name, schema_name]:\n    if not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", identifier):\n        raise ValueError("Catalog/schema must be simple SQL identifiers")\n\nbronze_table = f"{catalog_name}.{schema_name}.bronze_taxi_trips"\nsilver_table = f"{catalog_name}.{schema_name}.silver_taxi_trips"\ngold_fact_table = f"{catalog_name}.{schema_name}.gold_fact_taxi_trips"\ngold_zone_table = f"{catalog_name}.{schema_name}.gold_dim_zone"\ngold_date_table = f"{catalog_name}.{schema_name}.gold_dim_date"\nquarantine_table = f"{catalog_name}.{schema_name}.quarantine_taxi_trips"\naudit_table = f"{catalog_name}.{schema_name}.pipeline_audit"\nrecon_table = f"{catalog_name}.{schema_name}.pipeline_reconciliation"\n\nsource_url = f"https://d37ci6vzurychx.cloudfront.net/trip-data/yellow_tripdata_{process_year}-{process_month}.parquet"\n\nprint(source_url)\n\n# COMMAND ----------\n\n# DBTITLE 1,Create Schema\nspark.sql(f"CREATE SCHEMA IF NOT EXISTS {catalog_name}.{schema_name}")\n\n# COMMAND ----------\n\n# DBTITLE 1,Utility Functions\ndef pickup_date_bounds(year, month, grace_days):\n    if not isinstance(grace_days, int) or isinstance(grace_days, bool) or grace_days < 0:\n        raise ValueError("boundary_grace_days must be a nonnegative integer")\n    start = date(year, month, 1)\n    next_start = date(year + (month == 12), 1 if month == 12 else month + 1, 1)\n    return start - timedelta(days=grace_days), next_start + timedelta(days=grace_days)\n\n\ndef pickup_outside_allowed_window(timestamp_column):\n    lower, upper = pickup_date_bounds(int(process_year), int(process_month), boundary_grace_days)\n    pickup_day = F.to_date(F.col(timestamp_column))\n    return (pickup_day < F.lit(lower)) | (pickup_day >= F.lit(upper))\n\n\ndef utc_now():\n    return datetime.now(timezone.utc).isoformat()\n\n\ndef add_ingestion_metadata(df, source_name):\n    return (\n        df.withColumn("_batch_id", F.lit(batch_id))\n          .withColumn("_source_name", F.lit(source_name))\n          .withColumn("_ingested_at_utc", F.current_timestamp())\n          .withColumn("_process_year", F.lit(int(process_year)))\n          .withColumn("_process_month", F.lit(int(process_month)))\n    )\n\n\ndef write_audit_record(layer_name, table_name, status, source_count=None, target_count=None, rejected_count=None, error_message=None):\n    rows = [(\n        batch_id,\n        project_name,\n        layer_name,\n        table_name,\n        int(source_count) if source_count is not None else None,\n        int(target_count) if target_count is not None else None,\n        int(rejected_count) if rejected_count is not None else None,\n        status,\n        error_message,\n        run_started_at,\n        utc_now()\n    )]\n    schema = "batch_id string, project_name string, layer_name string, table_name string, source_count long, target_count long, rejected_count long, status string, error_message string, started_at_utc string, ended_at_utc string"\n    spark.createDataFrame(rows, schema).write.mode("append").format("delta").saveAsTable(audit_table)\n\n\ndef require_columns(df, required_columns):\n    missing = sorted(set(required_columns) - set(df.columns))\n    if missing:\n        raise ValueError(f"Missing required columns: {missing}")\n\n', '02_ingest_to_bronze': '# Databricks notebook source\n# MAGIC %md\n# MAGIC # 02 - Ingest To Bronze\n# MAGIC\n# MAGIC This notebook ingests one monthly NYC Taxi trip file and writes it to a bronze Delta table with ingestion metadata.\n\n# COMMAND ----------\n\n# MAGIC %run ./01_setup_and_config\n\n# COMMAND ----------\n\nimport os\nimport shutil\nfrom hashlib import sha256\nfrom urllib.request import urlopen\nfrom pyspark.sql import functions as F\n\n# COMMAND ----------\n\n# DBTITLE 1,Read Source Data\nyear = int(process_year)\nmonth = int(process_month)\nif not (2009 <= year <= datetime.now(timezone.utc).year and 1 <= month <= 12):\n    raise ValueError("Use a valid NYC taxi processing year and month")\n\nspark.sql(f"CREATE VOLUME IF NOT EXISTS {catalog_name}.{schema_name}.landing")\nlanding_directory = f"/Volumes/{catalog_name}/{schema_name}/landing/yellow/{year}/{month:02d}/{batch_id}"\nos.makedirs(landing_directory, exist_ok=True)\nlanding_file = f"{landing_directory}/yellow_tripdata_{year}-{month:02d}.parquet"\n\n\ndef read_monthly_taxi_file(url, destination):\n    """Stream the original file to a Volume before the distributed Spark read."""\n    try:\n        with urlopen(url, timeout=120) as response, open(destination, "wb") as target:\n            shutil.copyfileobj(response, target, length=1024 * 1024)\n        with open(destination, "rb") as downloaded:\n            if os.path.getsize(destination) < 12 or downloaded.read(4) != b"PAR1":\n                raise ValueError("Downloaded source is not a valid Parquet file")\n            downloaded.seek(-4, os.SEEK_END)\n            if downloaded.read(4) != b"PAR1":\n                raise ValueError("Downloaded Parquet file is incomplete")\n    except Exception:\n        if os.path.exists(destination):\n            os.remove(destination)\n        raise\n    return spark.read.parquet(destination)\n\n\nraw_df = read_monthly_taxi_file(source_url, landing_file)\nrequire_columns(raw_df, ["VendorID", "tpep_pickup_datetime", "tpep_dropoff_datetime", "passenger_count",\n                        "trip_distance", "PULocationID", "DOLocationID", "payment_type", "fare_amount", "total_amount"])\n# Normalize known source numeric drift to existing Bronze column types without allowing truncation.\nif spark.catalog.tableExists(bronze_table):\n    numeric_types = {"byte", "short", "integer", "long", "float", "double", "decimal"}\n    original_types = {field.name: field.dataType for field in raw_df.schema.fields}\n    for field in spark.table(bronze_table).schema.fields:\n        if field.name not in original_types or field.dataType == original_types[field.name]:\n            continue\n        source_type = original_types[field.name]\n        if source_type.typeName() not in numeric_types or field.dataType.typeName() not in numeric_types:\n            raise ValueError(f"Non-additive source schema change for {field.name}: {source_type} -> {field.dataType}")\n        coerced = F.col(field.name).cast(field.dataType)\n        lossy = raw_df.where(F.col(field.name).isNotNull() & (\n            coerced.isNull() | ~coerced.cast("decimal(38,12)").eqNullSafe(F.col(field.name).cast("decimal(38,12)"))\n        )).limit(1).count()\n        if lossy:\n            raise ValueError(f"Lossy source numeric schema change for {field.name}")\n        raw_df = raw_df.withColumn(field.name, coerced)\nsource_hasher = sha256()\nwith open(landing_file, "rb") as landed_source:\n    for chunk in iter(lambda: landed_source.read(1024 * 1024), b""):\n        source_hasher.update(chunk)\nsource_file_sha256 = source_hasher.hexdigest()\nprint(f"source_sha256={source_file_sha256}")\nsource_count = raw_df.count()\nif source_count == 0:\n    raise ValueError("Empty source: refusing to replace existing Bronze data")\n\nprint(f"landing_file={landing_file}")\nprint(f"source_count={source_count}")\ndisplay(raw_df.limit(10))\n\n# COMMAND ----------\n\n# DBTITLE 1,Write Bronze Delta Table\nbronze_df = add_ingestion_metadata(raw_df, source_url)\nmonth_predicate = f"_process_year = {int(process_year)} AND _process_month = {int(process_month)}"\n\n# Delta commits the selected month\'s replacement atomically, preserving other months.\n(\n    bronze_df.write\n    .format("delta")\n    .mode("overwrite")\n    .option("mergeSchema", "true")\n    .option("replaceWhere", month_predicate)\n    .partitionBy("_process_year", "_process_month")\n    .saveAsTable(bronze_table)\n)\n\ntarget_count = spark.table(bronze_table).where(month_predicate).count()\nif target_count != source_count:\n    write_audit_record("bronze", bronze_table, "FAILED", source_count, target_count, None, "Stored monthly count differs from source")\n    raise ValueError(f"Bronze reconciliation failed: source={source_count}, target={target_count}")\nwrite_audit_record("bronze", bronze_table, "SUCCESS", source_count, target_count, 0)\n\nprint(f"bronze_table={bronze_table}")\nprint(f"target_count={target_count}")\nprint("SUCCESS: monthly Bronze replacement and count reconciliation completed")\n\n', '03_quality_checks': '# Databricks notebook source\n# MAGIC %md\n# MAGIC # 03 - Quality Checks\n# MAGIC\n# MAGIC Apply configured quality rules, including the source-month pickup-date grace window, and replace that month\'s quarantine records. Original Bronze remains unchanged. Accepted rows are persisted by notebook 04.\n\n# COMMAND ----------\n\n# MAGIC %run ./01_setup_and_config\n\n# COMMAND ----------\n\nfrom pyspark.sql import functions as F\n\n# COMMAND ----------\n\n# DBTITLE 1,Load Current Batch From Bronze\nbronze_batch_df = (\n    spark.table(bronze_table)\n    .where((F.col("_process_year") == int(process_year)) & (F.col("_process_month") == int(process_month)))\n)\n\nrequired_columns = [\n    "VendorID",\n    "tpep_pickup_datetime",\n    "tpep_dropoff_datetime",\n    "passenger_count",\n    "trip_distance",\n    "PULocationID",\n    "DOLocationID",\n    "payment_type",\n    "fare_amount",\n    "total_amount"\n]\n\nrequire_columns(bronze_batch_df, required_columns)\n\nbronze_count = bronze_batch_df.count()\nif bronze_count == 0:\n    raise ValueError("No Bronze rows for this period. Run notebook 02 with matching year/month first.")\nprint(f"bronze_count={bronze_count}")\n\n# COMMAND ----------\n\n# DBTITLE 1,Build Validation Rules\nallowed_pickup_start, allowed_pickup_end = pickup_date_bounds(int(process_year), int(process_month), boundary_grace_days)\nprint(f"allowed_pickup_dates=[{allowed_pickup_start}, {allowed_pickup_end})")\nnumeric_errors = []\nfor numeric_name in ["trip_distance", "fare_amount", "total_amount"]:\n    numeric_value = F.expr(f"try_cast(`{numeric_name}` AS double)")\n    numeric_errors.append(F.when(\n        numeric_value.isNull() | F.isnan(numeric_value) | (F.abs(numeric_value) == F.lit(float("inf"))),\n        F.lit(f"missing_or_nonfinite_{numeric_name}")\n    ))\nvalidated_df = (\n    bronze_batch_df\n    .withColumn(\n        "_dq_error",\n        F.concat_ws(\n            "; ",\n            F.when(F.col("VendorID").isNull(), F.lit("missing_vendor_id")),\n            F.when(F.col("tpep_pickup_datetime").isNull(), F.lit("missing_pickup_datetime")),\n            F.when(F.col("tpep_dropoff_datetime").isNull(), F.lit("missing_dropoff_datetime")),\n            F.when(F.col("PULocationID").isNull(), F.lit("missing_pickup_location")),\n            F.when(F.col("DOLocationID").isNull(), F.lit("missing_dropoff_location")),\n            F.when(F.col("trip_distance") < 0, F.lit("negative_trip_distance")),\n            F.when(F.col("fare_amount") < 0, F.lit("negative_fare_amount")),\n            F.when(F.col("total_amount") < 0, F.lit("negative_total_amount")),\n            F.when(F.col("tpep_dropoff_datetime") < F.col("tpep_pickup_datetime"), F.lit("dropoff_before_pickup")),\n            F.when(pickup_outside_allowed_window("tpep_pickup_datetime"), F.lit("pickup_date_outside_allowed_window")),\n            *numeric_errors\n        )\n    )\n)\n\nvalid_df = validated_df.where(F.col("_dq_error") == "")\nreject_df = (\n    validated_df\n    .where(F.col("_dq_error") != "")\n    .withColumn("_rejected_at_utc", F.current_timestamp())\n)\n\nvalid_count = valid_df.count()\nreject_count = reject_df.count()\n\nprint(f"valid_count={valid_count}")\nprint(f"reject_count={reject_count}")\n\n# COMMAND ----------\n\n# DBTITLE 1,Write Quarantine Records\nif valid_count + reject_count != bronze_count:\n    write_audit_record("quality", quarantine_table, "FAILED", bronze_count, valid_count, reject_count, "Accepted plus rejected count differs from Bronze")\n    raise ValueError("Quality reconciliation failed: accepted + rejected must equal Bronze")\n\nmonth_predicate = f"_process_year = {int(process_year)} AND _process_month = {int(process_month)}"\n# Write even an empty reject set so a corrected month\'s stale rejects are removed.\n(\n    reject_df.write\n    .format("delta")\n    .mode("overwrite")\n    .option("mergeSchema", "true")\n    .option("replaceWhere", month_predicate)\n    .partitionBy("_process_year", "_process_month")\n    .saveAsTable(quarantine_table)\n)\n\nstored_reject_count = spark.table(quarantine_table).where(month_predicate).count()\nif stored_reject_count != reject_count:\n    write_audit_record("quality", quarantine_table, "FAILED", bronze_count, valid_count, stored_reject_count, "Stored quarantine count differs from flagged count")\n    raise ValueError("Quarantine reconciliation failed: stored count differs from flagged count")\n\nwrite_audit_record("quality", quarantine_table, "SUCCESS", bronze_count, valid_count, reject_count)\n\nprint(f"stored_reject_count={stored_reject_count}")\nprint("SUCCESS: initial quality checks and monthly quarantine replacement completed")\ndisplay(reject_df.limit(20))\n\n', '04_transform_to_silver': '# Databricks notebook source\n# MAGIC %md\n# MAGIC # 04 - Transform To Silver\n# MAGIC\n# MAGIC This notebook standardizes records accepted by notebook 03 and writes a monthly Silver snapshot. It preserves accepted source rows; no unique trip key has been established for deduplication.\n\n# COMMAND ----------\n\n# MAGIC %run ./03_quality_checks\n\n# COMMAND ----------\n\nfrom pyspark.sql import functions as F\n\n# COMMAND ----------\n\n# DBTITLE 1,Use Accepted Records From Quality Notebook\n# %run makes valid_df, counts, configuration, and audit helpers available here.\nprint(f"bronze_count={bronze_count}")\nprint(f"valid_count={valid_count}")\nprint(f"reject_count={reject_count}")\n\n# COMMAND ----------\n\n# DBTITLE 1,Standardize And Derive Columns\nsilver_standardized_df = (\n    valid_df\n    .withColumn("pickup_ts", F.col("tpep_pickup_datetime").cast("timestamp"))\n    .withColumn("dropoff_ts", F.col("tpep_dropoff_datetime").cast("timestamp"))\n    .withColumn("pickup_date", F.to_date("pickup_ts"))\n    .withColumn("trip_year", F.year("pickup_ts"))\n    .withColumn("trip_month", F.month("pickup_ts"))\n    .withColumn("trip_duration_minutes", (F.unix_timestamp("dropoff_ts") - F.unix_timestamp("pickup_ts")) / 60)\n    .withColumn("vendor_id", F.col("VendorID").cast("int"))\n    .withColumn("pickup_location_id", F.col("PULocationID").cast("int"))\n    .withColumn("dropoff_location_id", F.col("DOLocationID").cast("int"))\n    .withColumn("payment_type_id", F.col("payment_type").cast("int"))\n    .withColumn("passenger_count", F.col("passenger_count").cast("int"))\n    .withColumn("trip_distance", F.col("trip_distance").cast("double"))\n    .withColumn("fare_amount", F.col("fare_amount").cast("double"))\n    .withColumn("total_amount", F.col("total_amount").cast("double"))\n)\n\nsilver_df = (\n    silver_standardized_df\n    .select(\n        "vendor_id",\n        "pickup_ts",\n        "dropoff_ts",\n        "pickup_date",\n        "trip_year",\n        "trip_month",\n        "pickup_location_id",\n        "dropoff_location_id",\n        "payment_type_id",\n        "passenger_count",\n        "trip_distance",\n        "trip_duration_minutes",\n        "fare_amount",\n        "total_amount",\n        "_batch_id",\n        "_source_name",\n        "_ingested_at_utc",\n        "_process_year",\n        "_process_month"\n    )\n)\n\n# COMMAND ----------\n\n# DBTITLE 1,Write Silver Delta Table\nsource_count = bronze_count\ntarget_count = silver_df.count()\nif target_count != valid_count or target_count + reject_count != source_count:\n    write_audit_record("silver", silver_table, "FAILED", source_count, target_count, reject_count, "Silver rows do not reconcile with accepted Bronze rows")\n    raise ValueError("Silver reconciliation failed before writing")\n\nmonth_predicate = f"_process_year = {int(process_year)} AND _process_month = {int(process_month)}"\n\n(\n    silver_df.write\n    .format("delta")\n    .mode("overwrite")\n    .option("replaceWhere", month_predicate)\n    .partitionBy("_process_year", "_process_month")\n    .saveAsTable(silver_table)\n)\n\nstored_silver_count = spark.table(silver_table).where(month_predicate).count()\nif stored_silver_count != target_count:\n    write_audit_record("silver", silver_table, "FAILED", source_count, stored_silver_count, reject_count, "Stored Silver count differs from transformed count")\n    raise ValueError("Silver reconciliation failed after writing")\n\nwrite_audit_record("silver", silver_table, "SUCCESS", source_count, stored_silver_count, reject_count)\n\nprint(f"silver_table={silver_table}")\nprint(f"target_count={target_count}")\nprint(f"stored_silver_count={stored_silver_count}")\nprint("SUCCESS: Silver monthly replacement and count reconciliation completed")\ndisplay(silver_df.limit(10))\n\n', '05_build_gold_model': '# Databricks notebook source\n# MAGIC %md\n# MAGIC # 05 - Build Gold Model\n# MAGIC\n# MAGIC Load persisted Silver, download the official zone lookup, upsert shared dimensions, and replace only the selected source month\'s facts. Separate end-to-end reconciliation remains a later stage.\n\n# COMMAND ----------\n\n# MAGIC %run ./01_setup_and_config\n\n# COMMAND ----------\n\nimport csv\nimport io\nimport os\nfrom hashlib import sha256\nfrom urllib.request import urlopen\nfrom pyspark.sql import functions as F\n\n\ndef parse_zone_lookup(payload):\n    reader = csv.DictReader(io.StringIO(payload.decode("utf-8-sig")))\n    expected = {"LocationID", "Borough", "Zone", "service_zone"}\n    if not expected.issubset(set(reader.fieldnames or [])):\n        raise ValueError("Zone lookup is missing required CSV headers")\n    rows, seen = [], set()\n    for record in reader:\n        zone_id = int(record["LocationID"])\n        zone_name = (record["Zone"] or "").strip()\n        if zone_id <= 0 or zone_id in seen or not zone_name:\n            raise ValueError("Invalid/duplicate zone key or empty zone name")\n        seen.add(zone_id)\n        rows.append((zone_id, record["Borough"], zone_name, record["service_zone"]))\n    if not rows:\n        raise ValueError("Zone lookup is empty")\n    return rows\n\n\ndef upsert_dimension(df, table_name, key_name, view_name):\n    df.createOrReplaceTempView(view_name)\n    columns = df.columns\n    updates = ", ".join(f"t.{name} = s.{name}" for name in columns if name != key_name)\n    names = ", ".join(columns)\n    values = ", ".join(f"s.{name}" for name in columns)\n    # Preserve target keys absent from this month\'s updates.\n    spark.sql(f"""\n        MERGE INTO {table_name} AS t\n        USING {view_name} AS s ON t.{key_name} = s.{key_name}\n        WHEN MATCHED THEN UPDATE SET {updates}\n        WHEN NOT MATCHED THEN INSERT ({names}) VALUES ({values})\n    """)\n\n\ndef require_unique_keys(df, key_name):\n    if df.where(F.col(key_name).isNull()).limit(1).count():\n        raise ValueError(f"Dimension has null {key_name}")\n    if df.groupBy(key_name).count().where(F.col("count") > 1).limit(1).count():\n        raise ValueError(f"Dimension has duplicate {key_name}")\n\n\ndef fact_metrics(df):\n    # Rounded per-row cents are a comparison metric; source double fields remain unchanged.\n    return df.agg(\n        F.count(F.lit(1)).alias("row_count"),\n        F.coalesce(F.sum(F.col("total_amount").cast("decimal(20,2)") * 100), F.lit(0)).alias("total_cents"),\n        F.coalesce(F.sum(F.col("fare_amount").cast("decimal(20,2)") * 100), F.lit(0)).alias("fare_cents"),\n        F.coalesce(F.sum(F.when(F.col("total_amount").isNull(), 1).otherwise(0)), F.lit(0)).alias("total_nulls"),\n        F.coalesce(F.sum(F.when(F.col("fare_amount").isNull(), 1).otherwise(0)), F.lit(0)).alias("fare_nulls"),\n    ).first().asDict()\n\n\ndef check_fact_metrics(expected, actual):\n    if expected != actual:\n        raise ValueError(f"Silver/Gold metrics differ: silver={expected}, gold={actual}")\n\n# COMMAND ----------\n\n# DBTITLE 1,Load Persisted Silver Month\nmonth_predicate = f"_process_year = {int(process_year)} AND _process_month = {int(process_month)}"\nsilver_batch_df = spark.table(silver_table).where(month_predicate)\nrequire_columns(silver_batch_df, [\n    "pickup_date", "pickup_ts", "dropoff_ts", "vendor_id", "pickup_location_id",\n    "dropoff_location_id", "payment_type_id", "passenger_count", "trip_distance",\n    "trip_duration_minutes", "fare_amount", "total_amount", "_batch_id",\n    "_process_year", "_process_month"\n])\nsilver_metrics = fact_metrics(silver_batch_df)\nsilver_count = silver_metrics["row_count"]\nif silver_count == 0:\n    period_bronze_count = spark.table(bronze_table).where(month_predicate).count()\n    period_quarantine_count = spark.table(quarantine_table).where(month_predicate).count()\n    if period_bronze_count == 0 or period_quarantine_count != period_bronze_count:\n        raise ValueError("Empty Silver is allowed only when a nonempty Bronze month is fully quarantined")\n    print("All source rows quarantined: clearing the monthly Gold slice while preserving shared dimensions.")\nif silver_batch_df.where(F.col("pickup_date").isNull()).limit(1).count():\n    raise ValueError("Resolve Silver null pickup dates before creating Gold")\nprint(f"process_year={process_year}, process_month={process_month}")\nprint(f"silver_count={silver_count}")\n\n# COMMAND ----------\n\n# DBTITLE 1,Download And Validate Official TLC Zone Lookup\nzone_lookup_url = "https://d37ci6vzurychx.cloudfront.net/misc/taxi_zone_lookup.csv"\nmax_lookup_bytes = 2 * 1024 * 1024\nwith urlopen(zone_lookup_url, timeout=120) as response:\n    zone_payload = response.read(max_lookup_bytes + 1)\nif len(zone_payload) > max_lookup_bytes:\n    raise ValueError("Zone lookup exceeded the two-megabyte size limit")\nzone_rows = parse_zone_lookup(zone_payload)\nzone_lookup_sha256 = sha256(zone_payload).hexdigest()\nspark.sql(f"CREATE VOLUME IF NOT EXISTS {catalog_name}.{schema_name}.landing")\nreference_directory = f"/Volumes/{catalog_name}/{schema_name}/landing/reference/taxi_zones/{batch_id}"\nos.makedirs(reference_directory, exist_ok=True)\nzone_lookup_file = f"{reference_directory}/taxi_zone_lookup.csv"\nwith open(zone_lookup_file, "wb") as target:\n    target.write(zone_payload)\nprint(f"zone_lookup_file={zone_lookup_file}")\nprint(f"zone_lookup_sha256={zone_lookup_sha256}")\nprint(f"official_zone_count={len(zone_rows)}")\n\ndim_zone_df = (\n    spark.createDataFrame(\n        zone_rows + [(-1, "Unknown", "Unknown / unmapped location", "Unknown")],\n        "zone_id int, borough string, zone_name string, service_zone string"\n    )\n    .withColumn("zone_source", F.lit(zone_lookup_url))\n)\n\n# COMMAND ----------\n\n# DBTITLE 1,Upsert Shared Dimensions Without Removing Earlier Keys\ndim_date_df = (\n    silver_batch_df.select("pickup_date").distinct()\n    .withColumn("date_key", F.date_format("pickup_date", "yyyyMMdd").cast("int"))\n    .withColumn("year", F.year("pickup_date"))\n    .withColumn("month", F.month("pickup_date"))\n    .withColumn("day", F.dayofmonth("pickup_date"))\n    .withColumn("day_of_week", F.date_format("pickup_date", "EEEE"))\n    .withColumn("is_weekend", F.dayofweek("pickup_date").isin([1, 7]))\n)\nrequire_unique_keys(dim_date_df, "date_key")\nrequire_unique_keys(dim_zone_df, "zone_id")\nspark.sql(f"""CREATE TABLE IF NOT EXISTS {gold_date_table} (\n    pickup_date DATE, date_key INT, year INT, month INT, day INT,\n    day_of_week STRING, is_weekend BOOLEAN\n) USING DELTA""")\nspark.sql(f"""CREATE TABLE IF NOT EXISTS {gold_zone_table} (\n    zone_id INT, borough STRING, zone_name STRING, service_zone STRING, zone_source STRING\n) USING DELTA""")\n\nfor table_name, required, key in [\n    (gold_date_table, dim_date_df.columns, "date_key"),\n    (gold_zone_table, dim_zone_df.columns, "zone_id"),\n]:\n    existing = spark.table(table_name)\n    require_columns(existing, required)\n    require_unique_keys(existing, key)\n\nupsert_dimension(dim_date_df, gold_date_table, "date_key", "gold_date_updates")\nupsert_dimension(dim_zone_df, gold_zone_table, "zone_id", "gold_zone_updates")\ndate_dimension = spark.table(gold_date_table)\nzone_dimension = spark.table(gold_zone_table)\nrequire_unique_keys(date_dimension, "date_key")\nrequire_unique_keys(zone_dimension, "zone_id")\n\n# COMMAND ----------\n\n# DBTITLE 1,Build Trip Facts With Explicit Unknown Zone Mapping\n# Original location IDs remain for traceability; separate keys handle unmapped IDs.\npickup_keys = zone_dimension.select(F.col("zone_id").alias("_pickup_match"))\ndropoff_keys = zone_dimension.select(F.col("zone_id").alias("_dropoff_match"))\nfact_df = (\n    silver_batch_df\n    .join(pickup_keys, F.col("pickup_location_id") == F.col("_pickup_match"), "left")\n    .join(dropoff_keys, F.col("dropoff_location_id") == F.col("_dropoff_match"), "left")\n    .withColumn("pickup_zone_key", F.coalesce(F.col("_pickup_match"), F.lit(-1)))\n    .withColumn("dropoff_zone_key", F.coalesce(F.col("_dropoff_match"), F.lit(-1)))\n    .withColumn("date_key", F.date_format("pickup_date", "yyyyMMdd").cast("int"))\n    .select(\n        "date_key", "pickup_ts", "dropoff_ts", "vendor_id",\n        "pickup_location_id", "dropoff_location_id", "pickup_zone_key", "dropoff_zone_key",\n        "payment_type_id", "passenger_count", "trip_distance", "trip_duration_minutes",\n        "fare_amount", "total_amount", "_batch_id", "_process_year", "_process_month"\n    )\n)\ncheck_fact_metrics(silver_metrics, fact_metrics(fact_df))\nmissing_dates = fact_df.select("date_key").distinct().join(date_dimension.select("date_key"), "date_key", "left_anti")\nif missing_dates.limit(1).count():\n    raise ValueError("Gold facts contain date keys missing from the date dimension")\nunknown_zone_count = fact_df.where((F.col("pickup_zone_key") == -1) | (F.col("dropoff_zone_key") == -1)).count()\nprint(f"unknown_zone_trip_count={unknown_zone_count}")\n\n# COMMAND ----------\n\n# DBTITLE 1,Replace Monthly Facts And Verify Stored Metrics\n(\n    fact_df.write.format("delta").mode("overwrite")\n    .option("replaceWhere", month_predicate)\n    .partitionBy("_process_year", "_process_month")\n    .saveAsTable(gold_fact_table)\n)\nstored_fact_df = spark.table(gold_fact_table).where(month_predicate)\ngold_metrics = fact_metrics(stored_fact_df)\ntry:\n    check_fact_metrics(silver_metrics, gold_metrics)\n    for key in ["pickup_zone_key", "dropoff_zone_key"]:\n        missing = stored_fact_df.select(F.col(key).alias("zone_id")).distinct().join(\n            zone_dimension.select("zone_id"), "zone_id", "left_anti"\n        )\n        if missing.limit(1).count():\n            raise ValueError(f"Stored Gold has missing zone references: {key}")\n    missing_dates = stored_fact_df.select("date_key").distinct().join(date_dimension.select("date_key"), "date_key", "left_anti")\n    if missing_dates.limit(1).count():\n        raise ValueError("Stored Gold has missing date references")\nexcept Exception as error:\n    write_audit_record("gold", gold_fact_table, "FAILED", silver_count, gold_metrics["row_count"], None, str(error))\n    raise\n\nwrite_audit_record("gold", gold_fact_table, "SUCCESS", silver_count, gold_metrics["row_count"], 0)\nprint(f"gold_fact_table={gold_fact_table}")\nprint(f"silver_count={silver_count}")\nprint(f"stored_gold_count={gold_metrics[\'row_count\']}")\nprint(f"silver_total_cents={silver_metrics[\'total_cents\']}, gold_total_cents={gold_metrics[\'total_cents\']}")\nprint(f"silver_fare_cents={silver_metrics[\'fare_cents\']}, gold_fare_cents={gold_metrics[\'fare_cents\']}")\nprint(f"date_dimension_count={date_dimension.count()}")\nprint(f"zone_dimension_count={zone_dimension.count()}")\nprint("SUCCESS: Gold monthly facts, shared dimensions, count/amount checks and reference checks completed")\ndisplay(stored_fact_df.limit(10))\n\n', '06_reconciliation_and_audit': '# Databricks notebook source\n# MAGIC %md\n# MAGIC # 06 - Reconciliation And Audit\n# MAGIC\n# MAGIC Independently read persisted tables for one source month. Reconcile counts, rounded amount metrics, nulls, provenance and dimension references. Persist per-check results before raising on failure. Date-period anomalies are warnings, not silent deletions.\n# MAGIC\n# MAGIC Run sequentially with no upstream pipeline modifying these tables.\n\n# COMMAND ----------\n\n# MAGIC %run ./01_setup_and_config\n\n# COMMAND ----------\n\nfrom datetime import date\nfrom pyspark.sql import functions as F\n\n\ndef make_check(name, expected, actual, severity="ERROR", detail=""):\n    status = "PASS" if expected == actual else ("WARN" if severity == "WARN" else "FAIL")\n    return (name, severity, str(expected), str(actual), status, detail)\n\n\ndef overall_check_status(checks):\n    statuses = {row[4] for row in checks}\n    return "FAIL" if "FAIL" in statuses else ("WARN" if "WARN" in statuses else "PASS")\n\n\ndef metric_expressions():\n    expressions = [F.count(F.lit(1)).alias("row_count")]\n    for name in ["fare_amount", "total_amount"]:\n        amount = F.col(name)\n        decimal_amount = F.expr(f"try_cast(`{name}` AS decimal(20,2))")\n        double_amount = F.expr(f"try_cast(`{name}` AS double)")\n        expressions.extend([\n            F.coalesce(F.sum(decimal_amount * 100), F.lit(0)).alias(f"{name}_cents"),\n            F.coalesce(F.sum(F.when(amount.isNull(), 1).otherwise(0)), F.lit(0)).alias(f"{name}_nulls"),\n            F.coalesce(F.sum(F.when(\n                amount.isNotNull() & (\n                    decimal_amount.isNull() | F.isnan(double_amount) |\n                    (F.abs(double_amount) == F.lit(float("inf")))\n                ), 1\n            ).otherwise(0)), F.lit(0)).alias(f"{name}_invalid"),\n        ])\n    return expressions\n\n\ndef measure_layer(df):\n    return df.agg(*metric_expressions()).first().asDict()\n\n\ndef missing_key_count(facts, fact_key, dimension, dimension_key):\n    keys = facts.select(F.col(fact_key).alias("_reference_key")).distinct()\n    available = dimension.select(F.col(dimension_key).alias("_reference_key")).distinct()\n    return keys.join(available, "_reference_key", "left_anti").count()\n\n\ndef duplicate_key_groups(df, key):\n    return df.groupBy(key).count().where(F.col("count") > 1).count()\n\n# COMMAND ----------\n\n# DBTITLE 1,Load Persisted Source-Month Tables\nyear, month = int(process_year), int(process_month)\nperiod_start = date(year, month, 1)\nnext_month_start = date(year + (month == 12), 1 if month == 12 else month + 1, 1)\nmonth_predicate = f"_process_year = {year} AND _process_month = {month}"\nlayer_tables = {\n    "bronze": bronze_table, "quarantine": quarantine_table,\n    "silver": silver_table, "gold": gold_fact_table\n}\nlayers = {}\nfor layer, table_name in layer_tables.items():\n    df = spark.table(table_name).where(month_predicate)\n    require_columns(df, ["fare_amount", "total_amount", "_batch_id"])\n    layers[layer] = df\nrequire_columns(layers["quarantine"], ["_dq_error"])\nrequire_columns(layers["silver"], ["pickup_date", "pickup_ts", "pickup_location_id", "dropoff_location_id"])\nrequire_columns(layers["gold"], ["date_key", "pickup_ts", "pickup_location_id", "dropoff_location_id", "pickup_zone_key", "dropoff_zone_key"])\ndate_dimension = spark.table(gold_date_table)\nzone_dimension = spark.table(gold_zone_table)\nrequire_columns(date_dimension, ["date_key", "pickup_date"])\nrequire_columns(zone_dimension, ["zone_id"])\n\nmetrics = {name: measure_layer(df) for name, df in layers.items()}\nbronze_count = metrics["bronze"]["row_count"]\nquarantine_count = metrics["quarantine"]["row_count"]\nsilver_count = metrics["silver"]["row_count"]\ngold_count = metrics["gold"]["row_count"]\nprint(f"process_year={process_year}, process_month={process_month}")\nfor name, values in metrics.items():\n    print(f"{name}_count={values[\'row_count\']}")\n\n# COMMAND ----------\n\n# DBTITLE 1,Reconcile Counts, Amounts And Nulls\nchecks = [\n    make_check("bronze_has_rows", True, bronze_count > 0),\n    make_check("silver_rows_or_fully_quarantined", True, silver_count > 0 or (bronze_count > 0 and quarantine_count == bronze_count), detail="Empty accepted output is valid only for a fully quarantined nonempty source."),\n    make_check("bronze_equals_silver_plus_quarantine", bronze_count, silver_count + quarantine_count),\n    make_check("silver_equals_gold_rows", silver_count, gold_count),\n]\nfor amount in ["fare_amount", "total_amount"]:\n    for suffix in ["cents", "nulls", "invalid"]:\n        metric = f"{amount}_{suffix}"\n        checks.append(make_check(\n            f"bronze_split_{metric}", metrics["bronze"][metric],\n            metrics["silver"][metric] + metrics["quarantine"][metric],\n            detail="Cents are summed after rounding each source value to decimal(20,2)."\n        ))\n        checks.append(make_check(\n            f"silver_gold_{metric}", metrics["silver"][metric], metrics["gold"][metric]\n        ))\n    # Raw/rejected invalid values are evidence; only accepted/served values must be valid.\n    for layer in ["silver", "gold"]:\n        checks.append(make_check(f"{layer}_{amount}_invalid", 0, metrics[layer][f"{amount}_invalid"]))\n\nbad_reasons = layers["quarantine"].where(\n    F.col("_dq_error").isNull() | (F.trim(F.col("_dq_error")) == "")\n).count()\nchecks.append(make_check("quarantine_has_error_reasons", 0, bad_reasons))\n\n# COMMAND ----------\n\n# DBTITLE 1,Check Provenance And Shared Dimension References\nbronze_batches = layers["bronze"].select("_batch_id").distinct()\nfor layer in layers:\n    missing_batches = layers[layer].where(F.col("_batch_id").isNull()).count()\n    checks.append(make_check(f"{layer}_null_batch_ids", 0, missing_batches))\n    if layer != "bronze":\n        unexpected = layers[layer].select("_batch_id").distinct().join(\n            bronze_batches, "_batch_id", "left_anti"\n        ).count()\n        checks.append(make_check(f"{layer}_unexpected_bronze_batch_ids", 0, unexpected))\n\n# Full outer joins expose batches missing from either side, not just unknown IDs.\nbatch_metrics = None\nmetric_names = list(metrics["bronze"])\nfor layer, df in layers.items():\n    grouped = df.groupBy("_batch_id").agg(*metric_expressions()).select(\n        "_batch_id", *[F.col(name).alias(f"{layer}_{name}") for name in metric_names]\n    )\n    batch_metrics = grouped if batch_metrics is None else batch_metrics.join(grouped, "_batch_id", "full")\nbatch_mismatch = F.lit(False)\nfor name in metric_names:\n    b = F.coalesce(F.col(f"bronze_{name}"), F.lit(0))\n    q = F.coalesce(F.col(f"quarantine_{name}"), F.lit(0))\n    s = F.coalesce(F.col(f"silver_{name}"), F.lit(0))\n    g = F.coalesce(F.col(f"gold_{name}"), F.lit(0))\n    batch_mismatch = batch_mismatch | (b != s + q) | (s != g)\nbatch_mismatches = batch_metrics.where(batch_mismatch)\nchecks.append(make_check("per_batch_layer_metric_mismatches", 0, batch_mismatches.count()))\n\nfor dimension_name, df, key in [\n    ("date", date_dimension, "date_key"), ("zone", zone_dimension, "zone_id")\n]:\n    checks.append(make_check(f"{dimension_name}_null_keys", 0, df.where(F.col(key).isNull()).count()))\n    checks.append(make_check(f"{dimension_name}_duplicate_key_groups", 0, duplicate_key_groups(df, key)))\n\nfor fact_key, dimension, dimension_key in [\n    ("date_key", date_dimension, "date_key"),\n    ("pickup_zone_key", zone_dimension, "zone_id"),\n    ("dropoff_zone_key", zone_dimension, "zone_id"),\n]:\n    checks.append(make_check(f"gold_null_{fact_key}", 0, layers["gold"].where(F.col(fact_key).isNull()).count()))\n    checks.append(make_check(f"gold_missing_{fact_key}", 0,\n                             missing_key_count(layers["gold"], fact_key, dimension, dimension_key)))\n\ndate_mismatches = date_dimension.where(\n    F.col("pickup_date").isNull() |\n    (F.col("date_key") != F.date_format("pickup_date", "yyyyMMdd").cast("int"))\n).count()\nchecks.append(make_check("date_dimension_key_matches_date", 0, date_mismatches))\n\ngold_date_assignments = layers["gold"].where(\n    ~F.col("date_key").eqNullSafe(F.date_format(F.to_date("pickup_ts"), "yyyyMMdd").cast("int"))\n).count()\nchecks.append(make_check("gold_date_key_matches_pickup_timestamp", 0, gold_date_assignments))\nsilver_date_assignments = layers["silver"].where(\n    ~F.col("pickup_date").eqNullSafe(F.to_date("pickup_ts"))\n).count()\nchecks.append(make_check("silver_pickup_date_matches_timestamp", 0, silver_date_assignments))\n\nfor original, mapped in [("pickup_location_id", "pickup_zone_key"), ("dropoff_location_id", "dropoff_zone_key")]:\n    available = zone_dimension.select(F.col("zone_id").alias("_expected_zone_match")).distinct()\n    assignments = layers["gold"].join(available, F.col(original) == F.col("_expected_zone_match"), "left")\n    incorrect = assignments.where(\n        ~F.col(mapped).eqNullSafe(F.coalesce(F.col("_expected_zone_match"), F.lit(-1)))\n    ).count()\n    checks.append(make_check(f"gold_{mapped}_matches_original_location", 0, incorrect))\n\n# COMMAND ----------\n\n# DBTITLE 1,Report Source-Period Date And Unknown-Zone Warnings\noutside_period = layers["silver"].where(\n    (F.col("pickup_date") < F.lit(period_start)) |\n    (F.col("pickup_date") >= F.lit(next_month_start))\n)\nout_of_period_count = outside_period.count()\nallowed_pickup_start, allowed_pickup_end = pickup_date_bounds(year, month, boundary_grace_days)\noutside_allowed_silver = layers["silver"].where(pickup_outside_allowed_window("pickup_ts")).count()\noutside_allowed_gold = layers["gold"].where(pickup_outside_allowed_window("pickup_ts")).count()\nchecks.append(make_check(\n    "silver_pickup_date_outside_allowed_window", 0, outside_allowed_silver,\n    detail=f"Policy={date_policy_version}; allowed pickup dates [{allowed_pickup_start}, {allowed_pickup_end}); grace_days={boundary_grace_days}"\n))\nchecks.append(make_check(\n    "gold_pickup_date_outside_allowed_window", 0, outside_allowed_gold,\n    detail=f"Policy={date_policy_version}; rerun updated quality, Silver and Gold if this fails."\n))\nsilver_null_dates = layers["silver"].where(F.col("pickup_date").isNull()).count()\nchecks.append(make_check("silver_null_pickup_dates", 0, silver_null_dates))\nchecks.append(make_check(\n    "silver_pickup_date_outside_source_month", 0, out_of_period_count, "WARN",\n    f"Retained boundary spillover is still visible; policy={date_policy_version}, grace_days={boundary_grace_days}. Beyond-grace dates are separate critical checks."\n))\nunknown_count = layers["gold"].where(\n    (F.col("pickup_zone_key") == -1) | (F.col("dropoff_zone_key") == -1)\n).count()\nchecks.append(make_check(\n    "gold_unknown_zone_trips", 0, unknown_count, "WARN",\n    "Mapped unknown members preserve trips; investigate original location IDs."\n))\nsilver_dates = layers["silver"].groupBy("pickup_date").count().orderBy("pickup_date")\nprint(f"source_period_start={period_start}, next_period_start={next_month_start}")\nprint(f"silver_out_of_period_trip_count={out_of_period_count}")\nprint(f"allowed_pickup_dates=[{allowed_pickup_start}, {allowed_pickup_end})")\nprint(f"silver_outside_allowed_window_count={outside_allowed_silver}")\nprint(f"gold_outside_allowed_window_count={outside_allowed_gold}")\nprint(f"gold_unknown_zone_trip_count={unknown_count}")\nprint(f"shared_date_dimension_count={date_dimension.count()}")\nprint(f"current_period_distinct_pickup_dates={layers[\'silver\'].select(\'pickup_date\').distinct().count()}")\n\n# COMMAND ----------\n\n# DBTITLE 1,Persist Per-Check Results And Audit Before Failing\noverall_status = overall_check_status(checks)\ncheck_results_table = f"{recon_table}_checks"\nreconciled_at_utc = utc_now()\nresult_rows = [\n    (batch_id, process_year, process_month, name, severity, expected, actual,\n     status, detail, overall_status, reconciled_at_utc)\n    for name, severity, expected, actual, status, detail in checks\n]\nresult_schema = (\n    "batch_id string, process_year string, process_month string, check_name string, "\n    "severity string, expected_value string, actual_value string, check_status string, "\n    "detail string, overall_status string, reconciled_at_utc string"\n)\nresult_df = spark.createDataFrame(result_rows, result_schema)\n# Append execution history intentionally; never replace business data in this notebook.\nresult_df.write.format("delta").mode("append").saveAsTable(check_results_table)\nwrite_audit_record("reconciliation", check_results_table, overall_status,\n                   bronze_count, gold_count, quarantine_count)\nprint(f"reconciliation_checks_table={check_results_table}")\nprint(f"overall_status={overall_status}")\ndisplay(result_df.orderBy("check_status", "check_name"))\ndisplay(batch_mismatches.limit(20))\ndisplay(silver_dates)\ndisplay(outside_period.select("pickup_date", "pickup_ts", "dropoff_ts", "_batch_id").limit(20))\n\nif overall_status == "FAIL":\n    failed = [row[0] for row in checks if row[4] == "FAIL"]\n    raise ValueError(f"Reconciliation failed for {batch_id}: {failed}")\nelif overall_status == "WARN":\n    print("COMPLETED WITH WARNINGS: required checks passed; review date/reference warnings.")\nelse:\n    print("SUCCESS: all configured reconciliation checks passed.")\n\n'}
RUNTIME_MODULES = {'planning': '"""Calendar and HTTP planning. No Spark or Databricks dependencies."""\n\nfrom datetime import date\nimport re\nimport time\nfrom urllib.error import HTTPError, URLError\nfrom urllib.request import Request, urlopen\n\n\ndef parse_period(value):\n    if not isinstance(value, str) or not re.fullmatch(r\'\\d{4}-(0[1-9]|1[0-2])\', value):\n        raise ValueError(\'Source period must be YYYY-MM\')\n    year, month = map(int, value.split(\'-\'))\n    if year < 2009:\n        raise ValueError(\'Yellow taxi periods begin in 2009\')\n    return year, month\n\n\ndef shift_period(period, months):\n    year, month = parse_period(period)\n    index = year * 12 + month - 1 + months\n    return f\'{index // 12:04d}-{index % 12 + 1:02d}\'\n\n\ndef month_range(start, end):\n    parse_period(start)\n    parse_period(end)\n    if start > end:\n        raise ValueError(\'Start period must not follow end period\')\n    periods = []\n    while start <= end:\n        periods.append(start)\n        if len(periods) > 600:\n            raise ValueError(\'Limit a backfill to at most 600 months\')\n        start = shift_period(start, 1)\n    return periods\n\n\ndef due_period(today, lag_months=2):\n    if not isinstance(lag_months, int) or lag_months < 0:\n        raise ValueError(\'Publication lag must be a nonnegative calendar-month count\')\n    return shift_period(f\'{today.year:04d}-{today.month:02d}\', -lag_months)\n\n\ndef order_pending(periods, completed):\n    ordered = sorted(set(periods))\n    pending = sorted(set(ordered) - set(completed))\n    if not pending:\n        return []\n    # Current freshness must not wait behind years of historical backlog.\n    if ordered[-1] in pending:\n        return [ordered[-1]] + [p for p in pending if p != ordered[-1]]\n    return pending\n\n\ndef is_completed(status):\n    return status in {\'COMPLETED\', \'COMPLETED_WARN\'}\n\n\ndef source_url(period):\n    parse_period(period)\n    return f\'https://d37ci6vzurychx.cloudfront.net/trip-data/yellow_tripdata_{period}.parquet\'\n\n\ndef probe_source(url, opener=urlopen, sleep=time.sleep, attempts=3):\n    """Probe metadata; never read a whole source file to discover availability."""\n    method = \'HEAD\'\n    for attempt in range(attempts):\n        try:\n            request = Request(url, method=method, headers={\'User-Agent\': \'TaxiLakehousePortfolio/2\'})\n            try:\n                response = opener(request, timeout=30)\n            except HTTPError as error:\n                if error.code not in (405, 501) or method != \'HEAD\':\n                    raise\n                method = \'GET\'\n                response = opener(Request(url, headers={\'Range\': \'bytes=0-3\'}), timeout=30)\n            with response:\n                return {\'status\': \'AVAILABLE\', \'etag\': response.headers.get(\'ETag\'),\n                        \'last_modified\': response.headers.get(\'Last-Modified\'),\n                        \'content_length\': response.headers.get(\'Content-Length\')}\n        except HTTPError as error:\n            if error.code == 404:\n                return {\'status\': \'WAITING_FOR_SOURCE\', \'etag\': None, \'last_modified\': None, \'content_length\': None}\n            if error.code not in (408, 429, 500, 502, 503, 504) or attempt == attempts - 1:\n                raise\n            delay = min(10, 2 ** attempt)\n            retry_after = error.headers.get(\'Retry-After\') if error.headers else None\n            if retry_after and retry_after.isdigit():\n                delay = min(10, int(retry_after))\n            sleep(delay)\n        except (URLError, TimeoutError, ConnectionError, OSError):\n            if attempt == attempts - 1:\n                raise\n            sleep(min(10, 2 ** attempt))\n    raise RuntimeError(\'Source probe exhausted retries\')\n', 'execution': '"""Bounded controller and adapters. Spark is injected, not imported at module load."""\n\nfrom datetime import datetime, timezone\nimport re\nfrom uuid import uuid4\n\nfrom taxi_pipeline.planning import due_period, month_range, order_pending, parse_period, probe_source, source_url\n\nPRIORITY_STATUSES = (\'REVISION_PENDING\',\'FAILED\',\'STARTED\',\'STAGE_STARTED\',\'RETRY_WAITING_FOR_SOURCE\')\n\n\nclass PipelineStageError(RuntimeError):\n    def __init__(self, stage, message):\n        self.stage = stage\n        super().__init__(f\'{stage}: {message}\')\n\n\ndef policy_identity(bundle_digest, grace_days):\n    return f\'pipeline_v2:{bundle_digest[:16]}:grace={grace_days}\'\n\n\ndef run_controller(*, start, end, today, completed, policy_version, max_months,\n                   process, emit, probe=probe_source, dry_run=False, force=False, priority_pending=()):\n    due = due_period(today, 2)\n    end = end or due\n    if end > due:\n        raise ValueError(f\'{end} is not due yet; latest due source period is {due}\')\n    periods = month_range(start, end)\n    if isinstance(max_months, bool) or not isinstance(max_months, int) or not 1 <= max_months <= 30:\n        raise ValueError(\'max_months_per_run must be an integer from 1 to 30\')\n    if force and len(periods) != 1:\n        raise ValueError(\'Force reprocessing requires an explicit single-month range\')\n    pending = order_pending(periods, set() if force else set(completed))\n    recent = set(periods[-3:])\n    priority_pending = sorted(set(priority_pending)&set(periods),reverse=True)\n    candidates = list(dict.fromkeys([periods[-1]] + priority_pending + pending + list(reversed(periods[-3:]))))\n    result = dict(due_period=due, total_months=len(periods), processed=[], waiting=[],\n                  unchanged=[], notes=[], plan=candidates, dry_run=dry_run)\n    if dry_run:\n        return result\n    # Metadata checks are independent of the ETL budget: a long backlog must not\n    # prevent revisions from being discovered before they leave the recent window.\n    probe_cache, revised = {}, []\n    for period in reversed(periods[-3:]):\n        previous = None if force else completed.get(period)\n        if previous is None:\n            continue\n        try:\n            metadata = probe(source_url(period))\n        except Exception as error:\n            emit(status=\'FAILED\',stage=\'availability\',source_period=period,run_id=uuid4().hex,\n                 policy_version=policy_version,source_url=source_url(period),error_message=str(error)[:4000])\n            raise\n        probe_cache[period] = metadata\n        if metadata[\'status\'] == \'AVAILABLE\' and any(\n            new is not None and new != previous.get(key)\n            for key,new in [(\'source_etag\',metadata.get(\'etag\')),(\'source_last_modified\',metadata.get(\'last_modified\'))]\n        ):\n            revised.append(period)\n            # Persist discovery before processing: it must not vanish when the month ages out.\n            emit(status=\'REVISION_PENDING\',stage=\'availability\',source_period=period,run_id=uuid4().hex,\n                 policy_version=policy_version,source_url=source_url(period),\n                 source_etag=metadata.get(\'etag\'),source_last_modified=metadata.get(\'last_modified\'))\n    candidates = list(dict.fromkeys([periods[-1]] + revised + priority_pending + pending + list(reversed(periods[-3:]))))\n    for period in candidates:\n        previous = None if force else completed.get(period)\n        if previous is not None and period not in recent:\n            continue\n        if len(result[\'processed\']) >= max_months:\n            break\n        run_id = uuid4().hex\n        base = dict(source_period=period,run_id=run_id,policy_version=policy_version,\n                    source_url=source_url(period))\n        stage = \'availability\'\n        try:\n            metadata = probe_cache[period] if period in probe_cache else probe(base[\'source_url\'])\n            header_values = dict(source_etag=metadata.get(\'etag\'),source_last_modified=metadata.get(\'last_modified\'))\n            if metadata[\'status\'] == \'WAITING_FOR_SOURCE\':\n                result[\'waiting\'].append(period)\n                if previous is None:\n                    waiting_status = \'RETRY_WAITING_FOR_SOURCE\' if period in priority_pending else \'WAITING_FOR_SOURCE\'\n                    emit(status=waiting_status,stage=stage,**base,**header_values)\n                else:\n                    result[\'notes\'].append(f\'{period}: completed source now unavailable; retained stored data\')\n                continue\n            if previous is not None:\n                changed = any(new is not None and new != previous.get(key) for key,new in header_values.items())\n                if not changed:\n                    result[\'unchanged\'].append(period)\n                    if not any(header_values.values()):\n                        result[\'notes\'].append(f\'{period}: no usable revision metadata; use explicit force to rehash\')\n                    continue\n            emit(status=\'STARTED\',stage=\'pipeline\',**base,**header_values)\n            def progress(stage_name):\n                emit(status=\'STAGE_STARTED\',stage=stage_name,**base,**header_values)\n            stage = \'pipeline\'\n            output = process(period,run_id,progress)\n            if output[\'overall_status\'] not in (\'PASS\',\'WARN\'):\n                raise PipelineStageError(\'reconciliation\',\'Required checks did not pass\')\n            status = \'COMPLETED_WARN\' if output[\'overall_status\']==\'WARN\' else \'COMPLETED\'\n            attrs = {key: output.get(key) for key in [\n                \'bronze_count\',\'silver_count\',\'gold_count\',\'quarantine_count\',\'out_of_period_count\',\'source_sha256\']}\n            emit(status=status,stage=\'reconciliation\',**base,**header_values,**attrs)\n            result[\'processed\'].append(period)\n        except Exception as error:\n            emit(status=\'FAILED\',stage=getattr(error,\'stage\',stage),error_message=str(error)[:4000],**base)\n            raise\n    return result\n\n\ndef execute_stages(sources, period, run_id, *, spark, dbutils, grace_days, catalog, schema,\n                   progress, show_previews=False, display_fn=None):\n    year, month = parse_period(period)\n    context = {\n        \'process_year\':year,\'process_month\':month,\'boundary_grace_days\':grace_days,\n        \'catalog_name\':catalog,\'schema_name\':schema,\n        \'batch_id\':f\'nyc_taxi_lakehouse_{year}_{month:02d}_{run_id}\',\n        \'run_started_at\':datetime.now(timezone.utc).isoformat(timespec=\'microseconds\'),\n    }\n    namespace = dict(spark=spark,dbutils=dbutils,_pipeline_context=context,\n                     display=display_fn if show_previews and display_fn else lambda _:None)\n    for stage in [\'01_setup_and_config\',\'02_ingest_to_bronze\',\'03_quality_checks\',\n                  \'04_transform_to_silver\',\'05_build_gold_model\',\'06_reconciliation_and_audit\']:\n        progress(stage)\n        try:\n            # Sources are our generated, checksummed notebook Python, never downloaded instructions.\n            exec(compile(sources[stage], stage+\'.py\',\'exec\'),namespace)\n        except Exception as error:\n            raise PipelineStageError(stage,str(error)) from error\n    return {key:namespace[key] for key in [\'overall_status\',\'bronze_count\',\'silver_count\',\n            \'gold_count\',\'quarantine_count\',\'out_of_period_count\']} | {\n                \'source_sha256\':namespace.get(\'source_file_sha256\')}\n\n\nEVENT_SCHEMA = (\n    \'event_id string, run_id string, source_period string, status string, policy_version string, stage string, \'\n    \'bronze_count long, silver_count long, gold_count long, quarantine_count long, out_of_period_count long, \'\n    \'source_url string, source_sha256 string, source_etag string, source_last_modified string, \'\n    \'event_time_utc string, error_message string\'\n)\nEVENT_FIELDS = [field.strip().split()[0] for field in EVENT_SCHEMA.split(\',\')]\n\n\nclass SparkEventStore:\n    def __init__(self,spark,catalog=\'workspace\',schema=\'nyc_taxi_lakehouse\'):\n        if not all(re.fullmatch(r\'[A-Za-z_][A-Za-z0-9_]*\',name) for name in [catalog,schema]):\n            raise ValueError(\'Catalog/schema must be simple SQL identifiers\')\n        self.spark = spark\n        self.table = f\'{catalog}.{schema}.pipeline_month_events\'\n        spark.sql(f\'CREATE SCHEMA IF NOT EXISTS {catalog}.{schema}\')\n        spark.sql(f\'CREATE TABLE IF NOT EXISTS {self.table} ({EVENT_SCHEMA}) USING DELTA\')\n        missing = set(EVENT_FIELDS) - set(spark.table(self.table).columns)\n        if missing:\n            raise ValueError(f\'Operational table schema is incompatible; missing fields: {sorted(missing)}\')\n\n    def emit(self,**values):\n        values = dict(values,event_id=uuid4().hex,event_time_utc=datetime.now(timezone.utc).isoformat(timespec=\'microseconds\'))\n        rows = [tuple(values.get(key) for key in EVENT_FIELDS)]\n        self.spark.createDataFrame(rows,EVENT_SCHEMA).write.format(\'delta\').mode(\'append\').saveAsTable(self.table)\n\n    def latest(self,start,end):\n        # Identifiers are validated above; data filters use Spark columns rather than SQL interpolation.\n        from pyspark.sql import functions as F\n        from pyspark.sql.window import Window\n        df = self.spark.table(self.table).where((F.col(\'source_period\')>=start)&(F.col(\'source_period\')<=end))\n        window = Window.partitionBy(\'source_period\').orderBy(F.col(\'event_time_utc\').desc(),F.col(\'event_id\').desc())\n        return df.withColumn(\'_rn\',F.row_number().over(window)).where(F.col(\'_rn\')==1).drop(\'_rn\')\n\n    def completed(self,policy_version,start,end):\n        from pyspark.sql import functions as F\n        rows = (self.latest(start,end)\n                .where((F.col(\'policy_version\')==policy_version)&F.col(\'status\').isin(\'COMPLETED\',\'COMPLETED_WARN\'))\n                .select(\'source_period\',\'source_etag\',\'source_last_modified\').collect())\n        return {row[\'source_period\']:row.asDict() for row in rows}\n\n    def priority_pending(self,policy_version,start,end):\n        from pyspark.sql import functions as F\n        rows = (self.latest(start,end).where(\n            (F.col(\'policy_version\')==policy_version)&\n            F.col(\'status\').isin(*PRIORITY_STATUSES)\n        ).select(\'source_period\').collect())\n        return [row[\'source_period\'] for row in rows]\n'}
